# ===== SPACING CONSTANTS =====
# Standardized spacing scale for consistent UI
SPACING = {
    'xs': 4,
    'sm': 8,
    'md': 12,
    'lg': 16,
    'xl': 24,
    'xxl': 32
}

# Sidebar configuration
SIDEBAR_CONFIG = {
    'expanded_width': 220,
    'collapsed_width': 56,
    'item_height': 40,
    'section_header_height': 32,
    'icon_size': 20,
}


class SidebarNavigation:
    """
    Collapsible sidebar navigation component for the application.
    Replaces the tab-based navigation with a modern sidebar pattern.
    """

    def __init__(self, parent, colors, on_select_callback):
        """
        Initialize the sidebar navigation.

        Args:
            parent: Parent widget (usually a PanedWindow)
            colors: Color palette dict from the theme
            on_select_callback: Function to call when an item is selected (item_id)
        """
        self.parent = parent
        self.colors = colors
        self.on_select_callback = on_select_callback
        self.collapsed = False
        self.sections = []
        self.items = {}  # item_id -> (button, icon, label)
        self.current_item = None
        self.section_states = {}  # section_id -> expanded (bool)

        # Create main frame
        self.frame = tk.Frame(parent, bg=colors.get('sidebar', '#2D3748'),
                             width=SIDEBAR_CONFIG['expanded_width'])
        self.frame.pack_propagate(False)

        # Create collapse toggle at bottom FIRST (so it reserves space)
        self._create_collapse_toggle()

        # Create header with logo/title and collapse button
        self._create_header()

        # Create scrollable content area (fills remaining space)
        self._create_content_area()

    def _get_font(self):
        """Get platform-appropriate font."""
        import platform
        system = platform.system()
        if system == 'Darwin':
            return ('SF Pro Text', 11)
        elif system == 'Windows':
            return ('Segoe UI', 10)
        else:
            return ('Ubuntu', 10)

    def _get_sidebar_text_color(self):
        """Get the sidebar text color, with fallback."""
        return self.colors.get('sidebar_text', self.colors.get('text_inverse', '#FFFFFF'))

    def _create_header(self):
        """Create minimal header spacing."""
        # Just add some top padding - no title needed
        spacer = tk.Frame(self.frame, bg=self.colors.get('sidebar', '#2D3748'),
                         height=SPACING['md'])
        spacer.pack(fill='x')
        self.title_label = spacer  # Keep reference for update_colors compatibility

    def _create_content_area(self):
        """Create the content area for navigation items (no scrolling needed)."""
        # Simple frame for content - no scrolling, items should fit
        self.content_frame = tk.Frame(self.frame,
                                     bg=self.colors.get('sidebar', '#2D3748'))
        self.content_frame.pack(side='top', fill='both', expand=True)

        # Keep canvas reference as None for compatibility
        self.canvas = None
        self.scrollbar = None
        self.canvas_window = None

    def _on_content_configure(self, event):
        """No-op: scrolling disabled."""
        pass

    def _on_canvas_configure(self, event):
        """No-op: scrolling disabled."""
        pass

    def _bind_mousewheel(self):
        """No-op: scrolling disabled."""
        pass

    def _unbind_mousewheel(self):
        """No-op: scrolling disabled."""
        pass

    def _on_mousewheel(self, event):
        """No-op: scrolling disabled."""
        pass

    def _create_collapse_toggle(self):
        """Create the collapse/expand toggle button at the bottom."""
        toggle_frame = tk.Frame(self.frame, bg=self.colors.get('sidebar', '#2D3748'),
                               height=50)
        toggle_frame.pack(side='bottom', fill='x')
        toggle_frame.pack_propagate(False)

        # Separator above toggle
        separator = tk.Frame(toggle_frame, bg=self.colors.get('border', '#4A5568'), height=1)
        separator.pack(fill='x', pady=(0, SPACING['xs']))

        self.collapse_btn = tk.Button(toggle_frame,
                                     text="« Collapse",
                                     font=self._get_font(),
                                     bg=self.colors.get('sidebar', '#2D3748'),
                                     fg=self._get_sidebar_text_color(),
                                     activebackground=self.colors.get('sidebar_hover', '#3D4858'),
                                     activeforeground=self._get_sidebar_text_color(),
                                     relief='flat',
                                     bd=0,
                                     cursor='hand2',
                                     command=self.toggle_collapse)
        self.collapse_btn.pack(fill='x', padx=SPACING['sm'], pady=SPACING['xs'])

    def add_section(self, section_id, title, items, expanded=True):
        """
        Add a collapsible section with navigation items.

        Args:
            section_id: Unique identifier for the section
            title: Section header text
            items: List of tuples (item_id, icon, label)
            expanded: Whether section starts expanded
        """
        self.section_states[section_id] = expanded

        section_data = {
            'id': section_id,
            'title': title,
            'items': items,
            'header': None,
            'title_label': None,
            'content': None,
            'indicator': None
        }

        # Create section header
        header_frame = tk.Frame(self.content_frame,
                               bg=self.colors.get('sidebar', '#2D3748'),
                               cursor='hand2')
        header_frame.pack(fill='x', pady=(SPACING['sm'], 0))

        # Indicator (arrow)
        indicator = tk.Label(header_frame,
                            text='v' if expanded else '>',
                            font=(self._get_font()[0], 10),
                            bg=self.colors.get('sidebar', '#2D3748'),
                            fg=self._get_sidebar_text_color())
        indicator.pack(side='left', padx=(SPACING['md'], SPACING['xs']))
        section_data['indicator'] = indicator

        # Section title
        title_label = tk.Label(header_frame,
                              text=title.upper(),
                              font=(self._get_font()[0], 9, 'bold'),
                              bg=self.colors.get('sidebar', '#2D3748'),
                              fg=self._get_sidebar_text_color())
        title_label.pack(side='left', padx=SPACING['xs'])
        section_data['header'] = header_frame
        section_data['title_label'] = title_label

        # Content frame for items
        content_frame = tk.Frame(self.content_frame,
                                bg=self.colors.get('sidebar', '#2D3748'))
        if expanded:
            content_frame.pack(fill='x')
        section_data['content'] = content_frame

        # Bind click events to toggle
        def toggle_section(e=None):
            self._toggle_section(section_id)

        header_frame.bind('<Button-1>', toggle_section)
        indicator.bind('<Button-1>', toggle_section)
        title_label.bind('<Button-1>', toggle_section)

        # Add items
        for item_id, icon, label in items:
            self._add_nav_item(content_frame, item_id, icon, label)

        self.sections.append(section_data)

    def _toggle_section(self, section_id):
        """Toggle a section's expanded/collapsed state."""
        for section in self.sections:
            if section['id'] == section_id:
                expanded = self.section_states[section_id]
                self.section_states[section_id] = not expanded

                if expanded:
                    # Collapse - hide content but keep in hierarchy
                    section['content'].pack_forget()
                    section['indicator'].config(text='>')
                else:
                    # Expand - pack after the header to maintain position
                    section['content'].pack(fill='x', after=section['header'])
                    section['indicator'].config(text='v')
                break

    def _add_nav_item(self, parent, item_id, icon, label):
        """Add a navigation item to a section."""
        item_frame = tk.Frame(parent,
                             bg=self.colors.get('sidebar', '#2D3748'),
                             cursor='hand2',
                             height=SIDEBAR_CONFIG['item_height'])
        item_frame.pack(fill='x')
        item_frame.pack_propagate(False)

        # Icon label with fixed width for consistent alignment
        icon_label = tk.Label(item_frame,
                             text=icon,
                             font=(self._get_font()[0], 12),
                             bg=self.colors.get('sidebar', '#2D3748'),
                             fg=self._get_sidebar_text_color(),
                             width=4,
                             anchor='center')
        icon_label.pack(side='left', padx=(SPACING['xs'], 0))

        # Text label
        text_label = tk.Label(item_frame,
                             text=label,
                             font=self._get_font(),
                             bg=self.colors.get('sidebar', '#2D3748'),
                             fg=self._get_sidebar_text_color(),
                             anchor='w')
        text_label.pack(side='left', fill='x', expand=True, padx=SPACING['xs'])

        # Store references
        self.items[item_id] = {
            'frame': item_frame,
            'icon': icon_label,
            'label': text_label
        }

        # Bind events
        def on_enter(e):
            if self.current_item != item_id:
                hover_bg = self.colors.get('sidebar_hover', '#3D4858')
                item_frame.config(bg=hover_bg)
                icon_label.config(bg=hover_bg)
                text_label.config(bg=hover_bg)

        def on_leave(e):
            if self.current_item != item_id:
                sidebar_bg = self.colors.get('sidebar', '#2D3748')
                item_frame.config(bg=sidebar_bg)
                icon_label.config(bg=sidebar_bg)
                text_label.config(bg=sidebar_bg)

        def on_click(e):
            self.select_item(item_id)

        for widget in [item_frame, icon_label, text_label]:
            widget.bind('<Enter>', on_enter)
            widget.bind('<Leave>', on_leave)
            widget.bind('<Button-1>', on_click)

    def select_item(self, item_id):
        """Select and highlight a navigation item."""
        # Deselect previous item
        if self.current_item and self.current_item in self.items:
            prev = self.items[self.current_item]
            sidebar_bg = self.colors.get('sidebar', '#2D3748')
            prev['frame'].config(bg=sidebar_bg)
            prev['icon'].config(bg=sidebar_bg)
            prev['label'].config(bg=sidebar_bg)

        # Select new item
        if item_id in self.items:
            self.current_item = item_id
            item = self.items[item_id]
            accent = self.colors.get('accent', '#0078D4')
            item['frame'].config(bg=accent)
            item['icon'].config(bg=accent)
            item['label'].config(bg=accent)

            # Call the callback
            if self.on_select_callback:
                self.on_select_callback(item_id)

    def toggle_collapse(self):
        """Toggle between expanded and collapsed sidebar."""
        self.collapsed = not self.collapsed

        if self.collapsed:
            # Collapse to icon-only mode
            self.frame.config(width=SIDEBAR_CONFIG['collapsed_width'])
            self.collapse_btn.config(text='>>')

            # Hide section headers
            for section in self.sections:
                section['header'].pack_forget()

            # Hide text labels (icons remain visible)
            for item_id, item in self.items.items():
                item['label'].pack_forget()
        else:
            # Expand to full width
            self.frame.config(width=SIDEBAR_CONFIG['expanded_width'])
            self.collapse_btn.config(text='<< Collapse')

            # REBUILD entire content in correct order
            # First, remove all children from content_frame
            for widget in self.content_frame.winfo_children():
                widget.pack_forget()

            # Re-pack sections in order: header, then content (if section is expanded)
            for section in self.sections:
                section['header'].pack(fill='x', pady=(SPACING['sm'], 0))
                if self.section_states[section['id']]:
                    section['content'].pack(fill='x')

            # Re-pack text labels in each item frame (after their icons)
            for item_id, item in self.items.items():
                item['label'].pack(side='left', fill='x', expand=True, padx=SPACING['xs'])

    def update_colors(self, colors):
        """Update colors when theme changes."""
        self.colors = colors
        sidebar_bg = colors.get('sidebar', '#2D3748')
        text_color = colors.get('sidebar_text', colors.get('text_inverse', '#FFFFFF'))

        self.frame.config(bg=sidebar_bg)
        self.title_label.config(bg=sidebar_bg)  # title_label is now just a spacer frame
        if self.canvas is not None:
            self.canvas.config(bg=sidebar_bg)
        self.content_frame.config(bg=sidebar_bg)
        self.collapse_btn.config(bg=sidebar_bg, fg=text_color,
                                activebackground=colors.get('sidebar_hover', '#3D4858'),
                                activeforeground=text_color)

        # Update all items
        for item_id, item in self.items.items():
            bg = colors.get('accent', '#0078D4') if item_id == self.current_item else sidebar_bg
            item['frame'].config(bg=bg)
            item['icon'].config(bg=bg, fg=text_color)
            item['label'].config(bg=bg, fg=text_color)

        # Update section headers
        for section in self.sections:
            if section['header']:
                section['header'].config(bg=sidebar_bg)
                for child in section['header'].winfo_children():
                    child.config(bg=sidebar_bg, fg=text_color)
            if section['content']:
                section['content'].config(bg=sidebar_bg)


# ===== HELPER: ROBUST AUTOSCALE FLAG PARSE =====
# Pulled out of the metadata save / code-export sites so we share the same
# string-aware parsing the code generator uses (`bool("False")` is True in
# Python, so any path that just wraps the resolved value in `bool(...)` is
# wrong on the round-tripped CSV/JSON string path).

def _parse_autoscale_flag(raw, default: bool = False) -> bool:
    if raw is None:
        return default
    if isinstance(raw, str):
        return raw.strip().lower() in ('true', '1', 'yes')
    try:
        import math as _math
        if isinstance(raw, float) and _math.isnan(raw):
            return default
    except Exception:
        pass
    return bool(raw)


# ===== HELPER: IMBALANCE CATEGORY SUFFIX FOR FILENAMES =====

def _get_imbalance_suffix(imbalance_method: str | None) -> str:
    """Return a short category code suffix for model filenames based on imbalance method."""
    if not imbalance_method:
        return ""
    OVERSAMPLING = {'smote', 'adasyn', 'borderline_smote', 'smogn', 'oversample'}
    UNDERSAMPLING = {'random_undersampler', 'tomek_links', 'undersample'}
    HYBRID = {'smote_tomek', 'smote_enn', 'smotetomek'}
    WEIGHTING = {'class_weight', 'binning', 'rare_boost', 'balanced'}
    if imbalance_method in OVERSAMPLING:
        return "_OVR"
    elif imbalance_method in UNDERSAMPLING:
        return "_UND"
    elif imbalance_method in HYBRID:
        return "_HYB"
    elif imbalance_method in WEIGHTING:
        return "_WGT"
    return ""


# ===== SKLEARN-COMPATIBLE WRAPPER CLASSES =====
# These classes wrap models with preprocessing/wavelength selection
# and are sklearn-clonable (required for ensemble OOF predictions)

def _build_transform_from_config(config: dict):
    """
    Build a preprocessing transform function from configuration.

    This is factored out so wrapper classes can recreate transforms after cloning.
    Imports are done inside to avoid circular dependencies.
    """
    from spectral_predict.preprocess import SavgolDerivative, SNV, SavgolSmooth
    from spectral_predict.baseline import BaselinePolynomial, BaselineALS, BaselineAirPLS

    def transform(X):
        import numpy as np
        X_out = np.asarray(X, dtype=np.float64)

        # Apply smoothing first (if enabled)
        if config.get('smooth'):
            smoother = SavgolSmooth(window_length=config['smooth'], polyorder=2)
            X_out = smoother.fit_transform(X_out)

        # Apply baseline correction
        baseline = config.get('baseline')
        bl_params = config.get('baseline_params', {})
        if baseline == 'polynomial':
            bl = BaselinePolynomial(degree=bl_params.get('degree', 2))
            X_out = bl.fit_transform(X_out)
        elif baseline == 'als':
            bl = BaselineALS(
                lambda_=bl_params.get('lam', 1e5),
                p=bl_params.get('p', 0.01),
                niter=10,
            )
            X_out = bl.fit_transform(X_out)
        elif baseline == 'airpls':
            bl = BaselineAirPLS(
                lam=bl_params.get('lam', 1e5),
                max_iter=15,
            )
            X_out = bl.fit_transform(X_out)

        # Apply main preprocessing
        pt = config.get('type', 'raw')
        w = config.get('window', 15)

        if pt == 'raw':
            pass
        elif pt == 'snv':
            X_out = SNV().fit_transform(X_out)
        elif pt == 'deriv1':
            X_out = SavgolDerivative(deriv=1, window=w).fit_transform(X_out)
        elif pt == 'deriv2':
            X_out = SavgolDerivative(deriv=2, window=w).fit_transform(X_out)
        elif pt == 'deriv3':
            X_out = SavgolDerivative(deriv=3, window=w, polyorder=4).fit_transform(X_out)
        elif pt == 'deriv4':
            X_out = SavgolDerivative(deriv=4, window=w, polyorder=5).fit_transform(X_out)
        elif pt == 'snv_deriv1':
            X_out = SNV().fit_transform(X_out)
            X_out = SavgolDerivative(deriv=1, window=w).fit_transform(X_out)
        elif pt == 'snv_deriv2':
            X_out = SNV().fit_transform(X_out)
            X_out = SavgolDerivative(deriv=2, window=w).fit_transform(X_out)
        elif pt == 'snv_deriv3':
            X_out = SNV().fit_transform(X_out)
            X_out = SavgolDerivative(deriv=3, window=w, polyorder=4).fit_transform(X_out)
        elif pt == 'snv_deriv4':
            X_out = SNV().fit_transform(X_out)
            X_out = SavgolDerivative(deriv=4, window=w, polyorder=5).fit_transform(X_out)
        elif pt == 'deriv1_snv':
            X_out = SavgolDerivative(deriv=1, window=w).fit_transform(X_out)
            X_out = SNV().fit_transform(X_out)
        elif pt == 'deriv2_snv':
            X_out = SavgolDerivative(deriv=2, window=w).fit_transform(X_out)
            X_out = SNV().fit_transform(X_out)
        elif pt == 'deriv3_snv':
            X_out = SavgolDerivative(deriv=3, window=w, polyorder=4).fit_transform(X_out)
            X_out = SNV().fit_transform(X_out)
        elif pt == 'deriv4_snv':
            X_out = SavgolDerivative(deriv=4, window=w, polyorder=5).fit_transform(X_out)
            X_out = SNV().fit_transform(X_out)

        return X_out

    return transform


def _match_wavelengths_normalized(requested_cols, available_columns, precision=1):
    """
    Match wavelengths using exact precision matching after normalization.

    This function solves the CARS wavelength matching bug where tolerance-based
    matching (±0.5nm) could match wrong wavelengths or fail silently.

    Instead of tolerance-based matching, this:
    1. Rounds both requested and available wavelengths to the same precision
    2. Matches on the normalized string representation
    3. Tries multiple precision levels if initial match fails

    Args:
        requested_cols: List of wavelength column names (can be strings or floats)
        available_columns: Column names from the new DataFrame
        precision: Decimal places to round to (default 1)

    Returns:
        List of matched column names from available_columns

    Raises:
        KeyError: If any wavelength cannot be matched
    """
    # Build lookup dict: normalized wavelength string -> original column name
    col_lookup = {}
    col_names = list(available_columns)

    for col in col_names:
        try:
            col_float = float(col)
            normalized_key = f"{round(col_float, precision):.{precision}f}"
            if normalized_key not in col_lookup:
                col_lookup[normalized_key] = col
        except (ValueError, TypeError):
            continue

    # Match each requested wavelength
    matched_by_index = {}  # index -> matched column
    missing_by_index = {}  # index -> wavelength

    for idx, req_col in enumerate(requested_cols):
        try:
            req_float = float(req_col)
            normalized_key = f"{round(req_float, precision):.{precision}f}"
            if normalized_key in col_lookup:
                matched_by_index[idx] = col_lookup[normalized_key]
            else:
                missing_by_index[idx] = req_col
        except (ValueError, TypeError):
            # Non-numeric column - try direct string match
            if req_col in col_names:
                matched_by_index[idx] = req_col
            else:
                missing_by_index[idx] = req_col

    # Try different precision levels for missing wavelengths
    if missing_by_index:
        for alt_precision in [0, 2, 3]:
            if alt_precision == precision:
                continue

            # Rebuild lookup at alternative precision
            col_lookup_alt = {}
            for col in col_names:
                try:
                    col_float = float(col)
                    normalized_key = f"{round(col_float, alt_precision):.{alt_precision}f}"
                    if normalized_key not in col_lookup_alt:
                        col_lookup_alt[normalized_key] = col
                except (ValueError, TypeError):
                    continue

            # Try matching still-missing wavelengths
            still_missing = {}
            for idx, wl in missing_by_index.items():
                try:
                    wl_float = float(wl)
                    normalized_key = f"{round(wl_float, alt_precision):.{alt_precision}f}"
                    if normalized_key in col_lookup_alt:
                        matched_by_index[idx] = col_lookup_alt[normalized_key]
                    else:
                        still_missing[idx] = wl
                except (ValueError, TypeError):
                    still_missing[idx] = wl

            missing_by_index = still_missing
            if not missing_by_index:
                break

    # Report any still-missing wavelengths
    if missing_by_index:
        missing_wls = list(missing_by_index.values())
        raise KeyError(
            f"Could not match all wavelength columns. "
            f"Missing {len(missing_wls)} wavelengths: {missing_wls[:5]}{'...' if len(missing_wls) > 5 else ''}"
        )

    # Return matched columns in original order
    return [matched_by_index[i] for i in range(len(requested_cols))]


class WavelengthSubsetWrapper(BaseEstimator, RegressorMixin):
    """
    Sklearn-compatible wrapper that applies wavelength subsetting during fit and predict.

    This wrapper is clonable via sklearn.clone() because it inherits from BaseEstimator
    and implements get_params/set_params properly.

    FIXED: Uses exact precision matching instead of tolerance-based matching (±0.5nm)
    to solve the CARS wavelength mismatch bug in ensembles.
    """

    def __init__(self, pipeline=None, wavelength_cols=None):
        self.pipeline = pipeline
        self.wavelength_cols = wavelength_cols

    def _subset(self, X):
        """
        Subset X to selected wavelengths using exact precision matching.

        This method solves the CARS wavelength matching bug where tolerance-based
        matching (±0.5nm) could match wrong wavelengths or fail silently.
        """
        if self.wavelength_cols is None:
            return X

        if hasattr(X, 'loc'):
            # DataFrame - use column selection
            try:
                return X[self.wavelength_cols]
            except KeyError:
                # Column name type mismatch - use normalized precision matching
                # This fixes the CARS ensemble bug where float vs string columns caused issues
                matching_cols = _match_wavelengths_normalized(
                    self.wavelength_cols, X.columns, precision=1
                )
                return X[matching_cols]
        else:
            # numpy array - assume columns are already matched
            return X

    def fit(self, X, y):
        X_subset = self._subset(X)
        self.pipeline.fit(X_subset, y)
        return self

    def predict(self, X):
        X_subset = self._subset(X)
        return self.pipeline.predict(X_subset)

    def get_params(self, deep=True):
        return {'pipeline': self.pipeline, 'wavelength_cols': self.wavelength_cols}

    def set_params(self, **params):
        for key, value in params.items():
            setattr(self, key, value)
        return self


class GAPreprocessWrapper(BaseEstimator, RegressorMixin):
    """
    Sklearn-compatible wrapper for GA/NSGA preprocessing.

    Stores preprocessing config (not the transform function) so it can be cloned.
    The transform function is recreated from config when needed.
    """

    def __init__(self, pipeline=None, preprocess_config=None):
        self.pipeline = pipeline
        self.preprocess_config = preprocess_config
        self._transform = None

    @property
    def transform(self):
        """Lazily create transform function from config."""
        if self._transform is None and self.preprocess_config:
            self._transform = _build_transform_from_config(self.preprocess_config)
        return self._transform

    def fit(self, X, y):
        X_preproc = self.transform(X.values if hasattr(X, 'values') else X)
        self.pipeline.fit(X_preproc, y)
        return self

    def predict(self, X):
        X_preproc = self.transform(X.values if hasattr(X, 'values') else X)
        return self.pipeline.predict(X_preproc)

    def get_params(self, deep=True):
        return {'pipeline': self.pipeline, 'preprocess_config': self.preprocess_config}

    def set_params(self, **params):
        for key, value in params.items():
            setattr(self, key, value)
        # Reset transform cache if config changes
        if 'preprocess_config' in params:
            self._transform = None
        return self


class CombinedPreprocessWrapper(BaseEstimator, RegressorMixin):
    """
    Sklearn-compatible wrapper for combined preprocessing + wavelength selection (NSGA-II).

    Stores preprocessing config and column info (not the transform function) so it can be cloned.
    The transform function is recreated from config when needed.
    """

    def __init__(self, pipeline=None, preprocess_config=None, wavelength_cols=None, all_columns=None):
        self.pipeline = pipeline
        self.preprocess_config = preprocess_config
        self.wavelength_cols = wavelength_cols
        self.all_columns = all_columns
        self._transform = None
        self._col_indices = None

    @property
    def transform(self):
        """Lazily create transform function from config."""
        if self._transform is None and self.preprocess_config:
            self._transform = _build_transform_from_config(self.preprocess_config)
        return self._transform

    @property
    def col_indices(self):
        """Lazily compute column indices."""
        if self._col_indices is None and self.all_columns is not None and self.wavelength_cols is not None:
            all_cols_list = list(self.all_columns)
            self._col_indices = [all_cols_list.index(c) for c in self.wavelength_cols]
        return self._col_indices

    def _preprocess_and_subset(self, X):
        X_arr = X.values if hasattr(X, 'values') else X
        X_preproc = self.transform(X_arr)
        # Subset to selected wavelengths (after preprocessing)
        return X_preproc[:, self.col_indices]

    def fit(self, X, y):
        X_processed = self._preprocess_and_subset(X)
        self.pipeline.fit(X_processed, y)
        return self

    def predict(self, X):
        X_processed = self._preprocess_and_subset(X)
        return self.pipeline.predict(X_processed)

    def get_params(self, deep=True):
        return {
            'pipeline': self.pipeline,
            'preprocess_config': self.preprocess_config,
            'wavelength_cols': self.wavelength_cols,
            'all_columns': self.all_columns
        }

    def set_params(self, **params):
        for key, value in params.items():
            setattr(self, key, value)
        # Reset caches if relevant params change
        if 'preprocess_config' in params:
            self._transform = None
        if 'all_columns' in params or 'wavelength_cols' in params:
            self._col_indices = None
        return self


# ==================== CLASSIFIER WRAPPERS ====================
# These are classification-specific versions of the wrappers above.
# They inherit ClassifierMixin, expose predict_proba(), and have a classes_ property.


class WavelengthSubsetClassifierWrapper(BaseEstimator, ClassifierMixin):
    """
    Sklearn-compatible classifier wrapper that applies wavelength subsetting during fit and predict.

    This wrapper is clonable via sklearn.clone() because it inherits from BaseEstimator
    and implements get_params/set_params properly.

    FIXED: Uses exact precision matching instead of tolerance-based matching (±0.5nm)
    to solve the CARS wavelength mismatch bug in ensembles.
    """

    def __init__(self, pipeline=None, wavelength_cols=None):
        self.pipeline = pipeline
        self.wavelength_cols = wavelength_cols

    def _subset(self, X):
        """
        Subset X to selected wavelengths using exact precision matching.

        This method solves the CARS wavelength matching bug where tolerance-based
        matching (±0.5nm) could match wrong wavelengths or fail silently.
        """
        if self.wavelength_cols is None:
            return X

        if hasattr(X, 'loc'):
            # DataFrame - use column selection
            try:
                return X[self.wavelength_cols]
            except KeyError:
                # Column name type mismatch - use normalized precision matching
                # This fixes the CARS ensemble bug where float vs string columns caused issues
                matching_cols = _match_wavelengths_normalized(
                    self.wavelength_cols, X.columns, precision=1
                )
                return X[matching_cols]
        else:
            # numpy array - assume columns are already matched
            return X

    def fit(self, X, y):
        X_subset = self._subset(X)
        self.pipeline.fit(X_subset, y)
        return self

    def predict(self, X):
        X_subset = self._subset(X)
        return self.pipeline.predict(X_subset)

    def predict_proba(self, X):
        """Return probability predictions for classification."""
        X_subset = self._subset(X)
        if hasattr(self.pipeline, 'predict_proba'):
            return self.pipeline.predict_proba(X_subset)
        raise AttributeError(f"{type(self.pipeline).__name__} does not support predict_proba")

    @property
    def classes_(self):
        """Return classes from the underlying classifier."""
        if hasattr(self.pipeline, 'classes_'):
            return self.pipeline.classes_
        raise AttributeError(f"{type(self.pipeline).__name__} does not have classes_ attribute")

    def get_params(self, deep=True):
        return {'pipeline': self.pipeline, 'wavelength_cols': self.wavelength_cols}

    def set_params(self, **params):
        for key, value in params.items():
            setattr(self, key, value)
        return self


class GAPreprocessClassifierWrapper(BaseEstimator, ClassifierMixin):
    """
    Sklearn-compatible classifier wrapper for GA/NSGA preprocessing.

    Stores preprocessing config (not the transform function) so it can be cloned.
    The transform function is recreated from config when needed.
    """

    def __init__(self, pipeline=None, preprocess_config=None):
        self.pipeline = pipeline
        self.preprocess_config = preprocess_config
        self._transform = None

    @property
    def transform(self):
        """Lazily create transform function from config."""
        if self._transform is None and self.preprocess_config:
            self._transform = _build_transform_from_config(self.preprocess_config)
        return self._transform

    def fit(self, X, y):
        X_preproc = self.transform(X.values if hasattr(X, 'values') else X)
        self.pipeline.fit(X_preproc, y)
        return self

    def predict(self, X):
        X_preproc = self.transform(X.values if hasattr(X, 'values') else X)
        return self.pipeline.predict(X_preproc)

    def predict_proba(self, X):
        """Return probability predictions for classification."""
        X_preproc = self.transform(X.values if hasattr(X, 'values') else X)
        if hasattr(self.pipeline, 'predict_proba'):
            return self.pipeline.predict_proba(X_preproc)
        raise AttributeError(f"{type(self.pipeline).__name__} does not support predict_proba")

    @property
    def classes_(self):
        """Return classes from the underlying classifier."""
        if hasattr(self.pipeline, 'classes_'):
            return self.pipeline.classes_
        raise AttributeError(f"{type(self.pipeline).__name__} does not have classes_ attribute")

    def get_params(self, deep=True):
        return {'pipeline': self.pipeline, 'preprocess_config': self.preprocess_config}

    def set_params(self, **params):
        for key, value in params.items():
            setattr(self, key, value)
        # Reset transform cache if config changes
        if 'preprocess_config' in params:
            self._transform = None
        return self


class CombinedPreprocessClassifierWrapper(BaseEstimator, ClassifierMixin):
    """
    Sklearn-compatible classifier wrapper for combined preprocessing + wavelength selection (NSGA-II).

    Stores preprocessing config and column info (not the transform function) so it can be cloned.
    The transform function is recreated from config when needed.
    """

    def __init__(self, pipeline=None, preprocess_config=None, wavelength_cols=None, all_columns=None):
        self.pipeline = pipeline
        self.preprocess_config = preprocess_config
        self.wavelength_cols = wavelength_cols
        self.all_columns = all_columns
        self._transform = None
        self._col_indices = None

    @property
    def transform(self):
        """Lazily create transform function from config."""
        if self._transform is None and self.preprocess_config:
            self._transform = _build_transform_from_config(self.preprocess_config)
        return self._transform

    @property
    def col_indices(self):
        """Lazily compute column indices."""
        if self._col_indices is None and self.all_columns is not None and self.wavelength_cols is not None:
            all_cols_list = list(self.all_columns)
            self._col_indices = [all_cols_list.index(c) for c in self.wavelength_cols]
        return self._col_indices

    def _preprocess_and_subset(self, X):
        X_arr = X.values if hasattr(X, 'values') else X
        X_preproc = self.transform(X_arr)
        # Subset to selected wavelengths (after preprocessing)
        return X_preproc[:, self.col_indices]

    def fit(self, X, y):
        X_processed = self._preprocess_and_subset(X)
        self.pipeline.fit(X_processed, y)
        return self

    def predict(self, X):
        X_processed = self._preprocess_and_subset(X)
        return self.pipeline.predict(X_processed)

    def predict_proba(self, X):
        """Return probability predictions for classification."""
        X_processed = self._preprocess_and_subset(X)
        if hasattr(self.pipeline, 'predict_proba'):
            return self.pipeline.predict_proba(X_processed)
        raise AttributeError(f"{type(self.pipeline).__name__} does not support predict_proba")

    @property
    def classes_(self):
        """Return classes from the underlying classifier."""
        if hasattr(self.pipeline, 'classes_'):
            return self.pipeline.classes_
        raise AttributeError(f"{type(self.pipeline).__name__} does not have classes_ attribute")

    def get_params(self, deep=True):
        return {
            'pipeline': self.pipeline,
            'preprocess_config': self.preprocess_config,
            'wavelength_cols': self.wavelength_cols,
            'all_columns': self.all_columns
        }

    def set_params(self, **params):
        for key, value in params.items():
            setattr(self, key, value)
        # Reset caches if relevant params change
        if 'preprocess_config' in params:
            self._transform = None
        if 'all_columns' in params or 'wavelength_cols' in params:
            self._col_indices = None
        return self


def _is_wrapped_model(model):
    """
    Check if a model is a CARS/NSGA-II wrapped model.

    These wrappers contain pipelines with StandardScaler whose parameters
    should be preserved during ensemble CV. When models are wrapped, ensemble
    methods should use refit_base_models=False to prevent StandardScaler
    divergence that causes ~0.03 R² loss.

    Parameters
    ----------
    model : object
        A fitted model to check

    Returns
    -------
    bool
        True if the model is a wrapped model that should not be refitted
    """
    WRAPPED_TYPES = (
        'WavelengthSubsetWrapper', 'WavelengthSubsetClassifierWrapper',
        'GAPreprocessWrapper', 'GAPreprocessClassifierWrapper',
        'CombinedPreprocessWrapper', 'CombinedPreprocessClassifierWrapper'
    )
    return type(model).__name__ in WRAPPED_TYPES


def _infer_task_type_from_y(y) -> "str | None":
    """Best-effort auto-detect of task type from a target array/Series.

    Returns 'classification', 'regression', or None if indeterminate.

    Policy (Fix-B1 semantics, restored 2026-04-21 after sklearn
    type_of_target caused integer-stepped regression targets like burn
    temperatures {150, 250, ..., 850} and 3-value proportion columns to
    auto-flip to classification):

    - ``nunique() == 2`` (binary) → classification
    - non-numeric dtype (object / category / string) → classification
    - otherwise numeric with 3+ unique values → regression

    Integer-coded multiclass targets (e.g. labels {0, 1, 2}) therefore
    auto-detect as regression; the user must pick classification via the
    radio button. This matches user preference and avoids falsely
    flagging numeric regression targets as classification. The
    ``build_cv_splitter(..., y=y)`` guard and the Model Development
    preflight still re-check ``type_of_target`` at CV-build time, so an
    explicit classification + truly-continuous y combination is caught.
    """
    if y is None:
        return None
    try:
        y_clean = y.dropna() if hasattr(y, 'dropna') else y
        if len(y_clean) == 0:
            return None
        dtype = getattr(y_clean, 'dtype', None)
        if dtype is None:
            return None
        n_unique = y_clean.nunique() if hasattr(y_clean, 'nunique') else len(np.unique(y_clean))
    except (TypeError, ValueError):
        return None
    if n_unique == 2:
        return 'classification'
    if not pd.api.types.is_numeric_dtype(dtype):
        return 'classification'
    return 'regression'


def _detect_refine_task_type(config: dict, y: "pd.Series | None") -> tuple[str, str | None]:
    resolved_task = config.get("Task", "")
    inlier_label = None

    if resolved_task == "one_class":
        inlier_label = config.get("inlier_class_label", "") or config.get("inlier_class", "")
        inlier_label = str(inlier_label) if inlier_label else None
    elif resolved_task in ("regression", "classification"):
        pass
    else:
        inferred = _infer_task_type_from_y(y)
        resolved_task = inferred if inferred in ("regression", "classification") else "regression"

    return resolved_task, inlier_label


