def main():
    """Main entry point."""
    # Set AppUserModelID so Windows taskbar shows our icon, not the Python icon
    if sys.platform == 'win32':
        try:
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(
                'ASP.SpectralPredict.App.1'
            )
        except Exception:
            pass

    # T-45: route module-level logger.warning calls to a file under
    # <user_data_dir>/dasp.log. In the bundled PyInstaller GUI, stderr
    # is /dev/null (no console window), so corrupt-sidecar coercions,
    # WAL rejections, and capture-time Tk failures vanish without this.
    # Best-effort: errors here don't block app start.
    try:
        from spectral_predict.run_logging import setup_app_logger
        setup_app_logger()
    except Exception:
        pass

    # T-50: bound the slow disk leak from accumulated Optuna SQLite trial
    # archives. Runs after the app logger so cleanup warnings land in
    # dasp.log; runs before any new run writes its sidecar so the active-
    # run guard sees the previous (crashed-or-clean) sidecar, not ours.
    try:
        from spectral_predict.run_state import cleanup_old_sqlite_files
        deleted, freed = cleanup_old_sqlite_files()
        if deleted:
            import logging as _logging
            _logging.getLogger("spectral_predict").info(
                "T-50: cleaned up %d stale Optuna SQLite files (%.1f MB freed)",
                deleted, freed / 1_048_576,
            )
    except Exception:
        # GLM M1 / DeepSeek L2 (T-50 fix-of-fixes): preserve best-effort
        # contract but surface structural cleanup failures (TypeError etc.
        # — distinct from per-file warnings the function itself emits) to
        # dasp.log via debug. Without this they vanish silently.
        import logging as _logging
        _logging.getLogger("spectral_predict").debug(
            "T-50: cleanup failed (non-fatal)", exc_info=True
        )

    root = tk.Tk()

    # Set window icon (taskbar and title bar). Belt-and-suspenders:
    #   1. iconbitmap(default=...) sets the .ico for *every* future Toplevel and
    #      is what Windows reads for the taskbar group (combined with the
    #      AppUserModelID set above).
    #   2. iconphoto(True, <PNG>) is the cross-platform path. On Windows it
    #      sets a higher-resolution image used in the title bar / Alt-Tab; on
    #      macOS it's the *only* path that works (iconbitmap is a no-op there).
    # The previous version imported `from src.spectral_predict...` which
    # silently failed in both dev (editable install) and bundle (no `src`
    # package on sys.path), so the icon never loaded.
    try:
        from spectral_predict.resource_paths import get_resource_path

        ico_path = get_resource_path('asp_logo.ico')
        png_path = get_resource_path('asp_logo_final.png')

        if sys.platform != 'darwin' and ico_path.exists():
            root.iconbitmap(default=str(ico_path))

        if png_path.exists():
            from PIL import Image, ImageTk
            icon_img = ImageTk.PhotoImage(Image.open(png_path))
            root._app_icon_ref = icon_img  # prevent GC
            root.iconphoto(True, icon_img)
    except Exception as e:
        import traceback
        sys.stderr.write(f"[icon] Could not set window icon: {e}\n")
        traceback.print_exc(file=sys.stderr)

    app = SpectralPredictApp(root)

    # Initialize tier-based model selection (must be done after all UI is created)
    app._on_tier_changed()

    # Add menu bar
    menubar = tk.Menu(root)
    root.config(menu=menubar)

    # About menu (leftmost)
    about_menu = tk.Menu(menubar, tearoff=0)
    menubar.add_cascade(label="About", menu=about_menu)
    about_menu.add_command(label="About Spectral Predict", command=app._show_about)

    # Help menu
    help_menu = tk.Menu(menubar, tearoff=0)
    menubar.add_cascade(label="Help", menu=help_menu)
    help_menu.add_command(label="Quick Start", command=app._show_help)
    help_menu.add_command(label="User Guide (Online)", command=app._open_user_guide_online)
    help_menu.add_command(label="User Guide (Offline)", command=app._open_user_guide_offline)
    help_menu.add_separator()
    help_menu.add_command(label="Exit", command=lambda: _clean_shutdown(root))

    # Wire the window's [X] button to the same clean-shutdown path. Without
    # this, non-daemon threads from completed analyses (or stray matplotlib
    # figure destructors, joblib worker teardowns, etc.) can keep the Python
    # interpreter alive after the Tk root is destroyed — the user sees "no
    # window" but `SpectralPredict-py312.exe` lingers in Task Manager. Calling
    # os._exit(0) after root.destroy() is the belt-and-suspenders guarantee.
    root.protocol("WM_DELETE_WINDOW", lambda: _clean_shutdown(root))

    # T-11 D: after the GUI is fully built but before the user can interact,
    # check for an incomplete run from a previous session and offer to
    # resume. Use after(100) instead of after(0) — a tiny delay gives the
    # window manager time to finish rendering the main window before the
    # modal dialog pops. With after(0), on macOS Tk Aqua and on slow
    # Windows machines the dialog could appear behind the main window, or
    # the main window wouldn't render until the dialog was dismissed.
    # 100ms is below human perception, so users see no lag.
    root.after(100, app._check_for_incomplete_run)

    root.mainloop()

    # Defensive: if mainloop returned without WM_DELETE_WINDOW firing (e.g. a
    # call to root.quit() from somewhere we don't control), still force exit.
    _clean_shutdown(root)


def _clean_shutdown(root):
    """Tear down the GUI and force-terminate the process.

    root.destroy() breaks the mainloop; os._exit(0) guarantees no non-daemon
    threads or lingering subprocess handles keep the .exe alive in Task Manager
    after the window is gone. We skip normal sys.exit() (which runs atexit
    handlers and waits for non-daemon threads) because by the time the user
    closed the window they've explicitly asked for the app to go away.
    """
    try:
        root.destroy()
    except Exception:
        pass
    os._exit(0)


def run_import_tests():
    """Run comprehensive import tests for bundled app verification."""
    import sys

    REQUIRED_IMPORTS = [
        # Core scientific
        ("numpy", "Core scientific computing"),
        ("pandas", "Data manipulation"),
        ("scipy", "Scientific computing base"),
        ("scipy.stats", "Statistical functions"),
        ("scipy.signal", "Signal processing"),
        ("scipy.optimize", "Optimization"),
        # sklearn
        ("sklearn", "Machine learning base"),
        ("sklearn.cross_decomposition", "PLS regression"),
        ("sklearn.preprocessing", "Data preprocessing"),
        ("sklearn.model_selection", "Cross-validation"),
        ("sklearn.metrics", "Model metrics"),
        ("sklearn.linear_model", "Linear models"),
        ("sklearn.ensemble", "Ensemble methods"),
        ("sklearn.svm", "Support vector machines"),
        ("sklearn.neural_network", "Neural networks"),
        # Boosting models
        ("xgboost", "XGBoost gradient boosting"),
        ("lightgbm", "LightGBM gradient boosting"),
        ("catboost", "CatBoost gradient boosting"),
        # Optimization
        ("optuna", "Hyperparameter optimization"),
        ("pymoo", "Multi-objective optimization"),
        ("pymoo.algorithms.moo.nsga2", "NSGA-II algorithm"),
        # Imbalanced learning
        ("imblearn", "Imbalanced learning"),
        # Visualization
        ("matplotlib", "Plotting"),
        ("matplotlib.pyplot", "Plotting interface"),
        ("PIL", "Image processing"),
        # Utilities
        ("joblib", "Parallel processing"),
        ("numba", "JIT compilation"),
        # GUI
        ("tkinter", "GUI framework"),
        # File format
        ("openpyxl", "Excel support"),
        # pymoo extras
        ("pymoo.util.nds.non_dominated_sorting", "pymoo NDS"),
        ("moocore", "Multi-objective core"),
    ]

    print("=" * 60)
    print("Spectral Predict - Bundled App Import Test")
    print("=" * 60)
    print(f"\nPython: {sys.executable}")
    print(f"Version: {sys.version}")
    print()

    failed = []
    success_count = 0

    for module_name, description in REQUIRED_IMPORTS:
        try:
            __import__(module_name)
            print(f"  [OK] {module_name}")
            success_count += 1
        except Exception as e:
            print(f"  [FAIL] {module_name}: {e}")
            failed.append((module_name, str(e)))

    # Test XGBoost DLL
    print("\n--- Testing XGBoost DLL ---")
    try:
        import xgboost
        import numpy as np
        X = np.array([[1, 2], [3, 4]])
        y = np.array([0, 1])
        model = xgboost.XGBClassifier(n_estimators=1, verbosity=0)
        model.fit(X, y)
        print("  [OK] XGBoost DLL functional")
    except Exception as e:
        print(f"  [FAIL] XGBoost DLL: {e}")
        failed.append(("xgboost.dll", str(e)))

    # Test LightGBM DLL
    print("\n--- Testing LightGBM DLL ---")
    try:
        import lightgbm
        import numpy as np
        X = np.array([[1, 2], [3, 4]])
        y = np.array([0, 1])
        model = lightgbm.LGBMClassifier(n_estimators=1, verbosity=-1)
        model.fit(X, y)
        print("  [OK] LightGBM DLL functional")
    except Exception as e:
        print(f"  [FAIL] LightGBM DLL: {e}")
        failed.append(("lightgbm.dll", str(e)))

    print("\n" + "=" * 60)
    print("SUMMARY")
    print("=" * 60)
    print(f"\nImports: {success_count}/{len(REQUIRED_IMPORTS)}")

    if failed:
        print(f"\n{len(failed)} FAILED:")
        for mod, err in failed:
            print(f"  - {mod}: {err}")
        return 1
    else:
        print("\n[SUCCESS] ALL TESTS PASSED!")
        return 0


if __name__ == "__main__":
    # Check for --test flag
    if len(sys.argv) > 1 and sys.argv[1] == "--test":
        sys.exit(run_import_tests())
    main()
